from dataclasses import dataclass, field
from typing import Optional
from mashumaro import DataClassDictMixin
from mashumaro.helper import field_options
from mashumaro.config import BaseConfig

@dataclass
class Child(DataClassDictMixin):
    x: int
    y: str

@dataclass
class Parent(DataClassDictMixin):
    child: Child = field(metadata=field_options(flatten=True, flatten_prefix=True))
    class Config(BaseConfig):
        forbid_extra_keys = True

p = Parent(Child(1, 'a'))
assert p.to_dict() == {'child_x': 1, 'child_y': 'a'}, p.to_dict()
assert Parent.from_dict({'child_x': 1, 'child_y': 'a'}) == p

@dataclass
class OptionalParent(DataClassDictMixin):
    child: Optional[Child] = field(default=None, metadata=field_options(flatten=True))

assert OptionalParent().to_dict() == {}
assert OptionalParent.from_dict({}) == OptionalParent()
assert OptionalParent.from_dict({'x': 1, 'y': 'a'}) == OptionalParent(Child(1, 'a'))
